          "institution",
          "period"
        ],
        "properties": {
          "course": {
            "type": "string",
            "title": "Course"
          },
          "role": {
            "type": "string",
            "title": "Role"
          },
          "institution": {
            "type": "string",
            "title": "Institution"
          },
